import { useRef, useState } from "react";
import { StarFill } from "@material-symbols-svg/react/rounded";
import { cn } from "@registry/aikoz/lib/utils";
import { Breadcrumb, type BreadcrumbItem } from "@registry/aikoz/breadcrumb/breadcrumb";
import { ProgressBar, type ProgressLevel } from "@registry/aikoz/progress-bar/progress-bar";
import { EmptyState } from "@registry/aikoz/empty-state/empty-state";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface RankingBarItem {
  /** Clé stable — le libellé ne suffit pas si deux branches le partagent. */
  id: string;
  label: string;
  /** Sous-titre — un volume, un effectif. « 6 843 avis ». */
  meta?: string;
  /** Valeur classante, dans l'échelle [0, `max`]. */
  value: number;
  /** Niveau forcé — sinon déduit des seuils de `ProgressBar`. */
  level?: ProgressLevel;
  /** Éléments enfants. Absent ou vide = dernier niveau, la ligne n'est pas cliquable. */
  children?: RankingBarItem[];
}

export interface RankingBarsProps {
  /** Nom de la racine, utilisé par le fil d'Ariane après le premier forage. */
  rootLabel: string;
  /** Premier niveau. */
  items: RankingBarItem[];
  /** Borne haute de l'échelle — 5 pour une note, 100 pour un pourcentage. */
  max?: number;
  /** Ce que la valeur mesure — porte le nom accessible de chaque barre. */
  valueLabel: string;
  formatValue?: (v: number) => string;
  /** Étoile décorative après la valeur — pertinente pour une note, pas pour un pourcentage. */
  showRating?: boolean;
  /** Prévenu à chaque changement de niveau, avec le chemin complet. */
  onNavigate?: (chemin: RankingBarItem[]) => void;
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Classement en barres horizontales, forable sur plusieurs niveaux —
 * transposé du bloc « Classement par thématique » (Duty Free CDG).
 *
 * **Chaque ligne EST le bouton.** Contrairement à `GeoDrilldown` — dont le
 * graphique recharts est `aria-hidden` et exige un bouton « Explorer » séparé
 * dans un tableau — ce composant ne dessine rien en SVG : les lignes sont du
 * HTML natif, donc directement focalisables et activables. Le clic et
 * l'Entrée font la même chose, sans détour.
 *
 * **Une ligne sans enfants n'est pas un bouton.** La rendre cliquable sans
 * action promettrait un détail qui n'existe pas — même raisonnement que le
 * fil d'Ariane, qui ne lie jamais la page courante.
 *
 * Le niveau de couleur de `ProgressBar` reste déduit de ses seuils par
 * défaut (90 % / 60 % de `max`), pas forcé au vert : sur une échelle de note,
 * une thématique à 2,5/5 doit pouvoir remonter en `critical`, exactement
 * comme sur le reste du système.
 */
export function RankingBars({
  rootLabel,
  items,
  max = 5,
  valueLabel,
  formatValue = (v) => v.toLocaleString("fr-FR", { minimumFractionDigits: 1, maximumFractionDigits: 1 }),
  showRating = true,
  onNavigate,
  className,
}: RankingBarsProps) {
  const [chemin, setChemin] = useState<RankingBarItem[]>([]);
  // L'annonce du changement de niveau : sans elle, un lecteur d'écran voit la
  // liste se réécrire sans savoir pourquoi. Même dispositif que `GeoDrilldown`.
  const [annonce, setAnnonce] = useState("");
  const ancre = useRef<HTMLDivElement | null>(null);

  const niveau = chemin.length === 0 ? items : (chemin[chemin.length - 1].children ?? []);

  const aller = (suite: RankingBarItem[]) => {
    setChemin(suite);
    const niveauSuivant = suite.length === 0 ? items : (suite[suite.length - 1].children ?? []);
    const nom = suite.length === 0 ? rootLabel : suite[suite.length - 1].label;
    setAnnonce(
      `${nom} — ${niveauSuivant.length} élément${niveauSuivant.length > 1 ? "s" : ""}.`
    );
    onNavigate?.(suite);
    // Le focus suit le forage : la ligne qu'on vient d'activer disparaît du
    // document avec l'ancien niveau. Sans reprise, il retombe sur `body`.
    requestAnimationFrame(() => ancre.current?.focus());
  };

  const fil: BreadcrumbItem[] = [
    { label: rootLabel, onClick: chemin.length ? () => aller([]) : undefined },
    ...chemin.map((it, i) => ({
      label: it.label,
      onClick: i < chemin.length - 1 ? () => aller(chemin.slice(0, i + 1)) : undefined,
    })),
  ];

  const titre = chemin.length === 0 ? rootLabel : chemin[chemin.length - 1].label;

  return (
    <div className={cn("flex flex-col gap-3", className)}>
      {chemin.length > 0 && <Breadcrumb items={fil} label={`Niveaux — ${valueLabel}`} />}

      <div ref={ancre} tabIndex={-1} className="outline-none">
        {/* Région live : c'est elle qui dit qu'on a changé de niveau. */}
        <p role="status" aria-live="polite" className="sr-only">
          {annonce}
        </p>

        {niveau.length === 0 ? (
          <EmptyState
            density="compact"
            title={`Aucune donnée sous ${titre}`}
            description="Ce niveau ne se décompose pas davantage."
          />
        ) : (
          <ul className="m-0 flex list-none flex-col gap-1 p-0">
            {niveau.map((it) => {
              const forable = !!it.children?.length;
              // Portée par la ligne elle-même (aria-label du bouton/de la
              // div) : la barre imbriquée reste décorative pour ne pas
              // dupliquer l'annonce d'un `role="meter"` niché dans un bouton.
              const accessibleLabel = `${it.label} — ${formatValue(it.value)} sur ${max}, ${valueLabel}${
                it.meta ? `, ${it.meta}` : ""
              }`;
              const contenu = (
                <>
                  <span aria-hidden="true" className="flex min-w-0 flex-1 flex-col gap-0.5">
                    <span className="truncate text-sm font-bold text-foreground">{it.label}</span>
                    {it.meta && (
                      <span className="truncate text-xs text-muted-foreground">{it.meta}</span>
                    )}
                  </span>
                  <ProgressBar
                    value={it.value}
                    max={max}
                    level={it.level}
                    label={null}
                    className="w-28 shrink-0 sm:w-48"
                  />
                  <span
                    aria-hidden="true"
                    className="flex shrink-0 items-center gap-1 text-sm font-black tabular-nums text-foreground"
                  >
                    {formatValue(it.value)}
                    {showRating && (
                      <StarFill className="size-4" style={{ color: "var(--rating)" }} />
                    )}
                  </span>
                </>
              );

              return (
                <li key={it.id}>
                  {forable ? (
                    <button
                      type="button"
                      onClick={() => aller([...chemin, it])}
                      aria-label={accessibleLabel}
                      className={cn(
                        "flex min-h-11 w-full items-center gap-4 rounded-[var(--radius)]",
                        "bg-transparent px-2 py-1.5 text-left transition-colors cursor-pointer",
                        "hover:bg-[var(--surface-hover)]",
                        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
                        "focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]"
                      )}
                    >
                      {contenu}
                    </button>
                  ) : (
                    <div
                      role="group"
                      aria-label={accessibleLabel}
                      className="flex min-h-11 w-full items-center gap-4 px-2 py-1.5"
                    >
                      {contenu}
                    </div>
                  )}
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
}

import { Fragment, type ReactNode } from "react";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface BreadcrumbItem {
  label: string;
  /** Absent sur le dernier élément : la page courante n'est pas un lien. */
  href?: string;
  /**
   * Remonte d'un niveau **sans changer d'URL** — cas d'un forage dans une
   * même vue (`GeoDrilldown`). Un `<button>` est alors rendu à la place du
   * lien : ce n'est pas une navigation, et l'annoncer comme telle tromperait.
   * Ignoré si `href` est fourni.
   */
  onClick?: () => void;
  /** Icône décorative — une maison sur la racine, en général. */
  icon?: ReactNode;
}

export interface BreadcrumbProps {
  items: BreadcrumbItem[];
  /** Nom du `<nav>`. « Fil d'Ariane » par défaut. */
  label?: string;
  /**
   * Séparateur. Toujours `aria-hidden` : il est visuel. La structure est
   * portée par la liste ordonnée, que les lecteurs d'écran annoncent déjà
   * « liste de 4 éléments, élément 3 ».
   */
  separator?: ReactNode;
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Fil d'Ariane.
 *
 * Un `<nav>` nommé, une `<ol>` — l'ordre porte du sens, ce n'est pas une
 * `<ul>` —, et **le dernier élément n'est pas un lien**. C'est la faute la
 * plus courante du motif : rendre la page courante cliquable produit un lien
 * qui ne mène nulle part, et prive `aria-current="page"` de son support.
 *
 * Le séparateur est décoratif et masqué. Un « / » lu à voix haute entre
 * chaque niveau n'apporte rien : la liste ordonnée dit déjà la profondeur.
 *
 * **Ce composant ne replie pas les niveaux intermédiaires.** Un fil trop long
 * pour sa largeur passe à la ligne. Le repli en « … » est une bonne idée sur
 * un site profond, mais il masque des niveaux à tout le monde pour un
 * problème de place, et il demande son propre contrat clavier — ce sera une
 * variante explicite le jour où une arborescence le justifie.
 */
export function Breadcrumb({
  items,
  label = "Fil d'Ariane",
  separator = "/",
  className,
}: BreadcrumbProps) {
  return (
    <nav aria-label={label} className={className}>
      <ol className="flex flex-wrap items-center gap-1.5 list-none m-0 p-0 text-sm">
        {items.map((item, i) => {
          const dernier = i === items.length - 1;
          const contenu = (
            <>
              {item.icon && (
                <span aria-hidden="true" className="inline-flex shrink-0 [&>svg]:size-4">
                  {item.icon}
                </span>
              )}
              {item.label}
            </>
          );

          return (
            <Fragment key={`${item.label}-${i}`}>
              <li className="inline-flex items-center">
                {!dernier && item.onClick && !item.href ? (
                  <button
                    type="button"
                    onClick={item.onClick}
                    className={cn(
                      "inline-flex items-center gap-1.5 rounded-[calc(var(--radius)/2)]",
                      // 24 px est le plancher du critère WCAG 2.2 AA 2.5.8.
                      // Mesuré ici avant correction : 20 px — la hauteur de
                      // ligne de `text-sm`. L'exception « cible dans une
                      // phrase » ne s'applique pas : un fil d'Ariane est une
                      // liste de navigation, pas du texte courant.
                      "min-h-6 tactile:min-h-11 tactile:px-1",
                      // Même soulignement au repos que le lien : c'est le seul
                      // signe qu'on peut agir dessus, et la couleur seule ne
                      // suffit pas (WCAG 1.4.1).
                      "text-muted-foreground underline underline-offset-2",
                      "hover:text-foreground",
                      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
                      "focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]"
                    )}
                  >
                    {contenu}
                  </button>
                ) : dernier || !item.href ? (
                  <span
                    // `aria-current="page"` sur un `<span>`, pas sur un lien :
                    // c'est ce qui dit « vous êtes ici » sans promettre une
                    // navigation qui n'aura pas lieu.
                    aria-current={dernier ? "page" : undefined}
                    className={cn(
                      "inline-flex items-center gap-1.5",
                      dernier
                        ? "font-medium text-foreground"
                        : "text-muted-foreground"
                    )}
                  >
                    {contenu}
                  </span>
                ) : (
                  <a
                    href={item.href}
                    className={cn(
                      "inline-flex items-center gap-1.5 rounded-[calc(var(--radius)/2)]",
                      // 24 px est le plancher du critère WCAG 2.2 AA 2.5.8.
                      // Mesuré ici avant correction : 20 px — la hauteur de
                      // ligne de `text-sm`. L'exception « cible dans une
                      // phrase » ne s'applique pas : un fil d'Ariane est une
                      // liste de navigation, pas du texte courant.
                      "min-h-6 tactile:min-h-11 tactile:px-1",
                      // Le soulignement est là AU REPOS, pas seulement au
                      // survol : dans un fil d'Ariane rien d'autre ne
                      // distingue un lien d'un simple mot, et la couleur
                      // seule ne suffit pas (WCAG 1.4.1).
                      "text-muted-foreground underline underline-offset-2",
                      "hover:text-foreground",
                      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
                      "focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]"
                    )}
                  >
                    {contenu}
                  </a>
                )}
              </li>
              {!dernier && (
                <li aria-hidden="true" className="text-muted-foreground select-none">
                  {separator}
                </li>
              )}
            </Fragment>
          );
        })}
      </ol>
    </nav>
  );
}

import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Variants ────────────────────────────────────────────────────────────────

const trackVariants = cva(
  // --track, pas --muted : en dark ce dernier vaut exactement --card (1,00:1),
  // la piste y serait strictement invisible.
  ["relative w-full overflow-hidden rounded-full", "bg-[var(--track)]"],
  {
    variants: {
      size: {
        sm: "h-1.5",
        md: "h-2",
        lg: "h-3",
      },
    },
    defaultVariants: { size: "md" },
  }
);

// Rôles de REMPLISSAGE, pas rôles de texte : un aplat porteur s'audite contre
// la piste au seuil 3:1 (WCAG 1.4.11), là où un texte s'audite à 4,5:1 contre
// la surface.
//
// Le jaune a imposé une sortie par le haut. En thème clair, l'aplat vif du
// thème sombre (#F0C420) ne donne que 1,40:1 sur la piste ; le forcer à
// respecter 3:1 seul le rendait brun (#8C6800), soit une barre d'une couleur
// que le thème sombre n'a nulle part. On applique donc au remplissage le
// dispositif déjà retenu pour Badge : le CONTOUR porte la limite, l'aplat
// reste libre. Résultat, le même jaune dans les deux thèmes — et 3:1 tenu par
// un liseré 1 px, invisible en sombre où l'aplat passait déjà seul.
const FILL: Record<ProgressLevel, { bg: string; edge: string }> = {
  good: { bg: "var(--success-fill)", edge: "var(--success-fill-edge)" },
  warning: { bg: "var(--warning-fill)", edge: "var(--warning-fill-edge)" },
  critical: { bg: "var(--error-fill)", edge: "var(--error-fill-edge)" },
};

// ─── Types ────────────────────────────────────────────────────────────────────

export type ProgressLevel = "good" | "warning" | "critical";

/**
 * `meter` — une MESURE dans une échelle connue : taux de réponse, note, jauge.
 * `progressbar` — l'avancement d'une TÂCHE : téléversement, import, calcul.
 *
 * ARIA distingue les deux et les lecteurs d'écran ne les annoncent pas pareil.
 * Le défaut est `meter` : dans ce design system la barre sert des indicateurs,
 * pas des traitements en cours.
 */
export type ProgressRole = "meter" | "progressbar";

export interface ProgressBarProps extends VariantProps<typeof trackVariants> {
  /** Valeur atteinte. Bornée à [0, max]. */
  value: number;
  /** Borne haute de l'échelle. */
  max?: number;
  /**
   * Niveau, qui porte la couleur. Omis, il est déduit de `thresholds` — et la
   * couleur est alors redondante avec la longueur, aucune information n'est
   * portée par la seule couleur.
   *
   * À forcer quand « moins » est un progrès (un délai de réponse bas est bon).
   * Attention : un niveau forcé porte une information que la longueur ne double
   * PAS — passer alors un `valueText` qui l'énonce, sous peine de tomber sous
   * le coup de WCAG 1.4.1.
   */
  level?: ProgressLevel;
  /**
   * Seuils de déduction du niveau, en fraction de `max`.
   * Au-dessus de `good` → good ; au-dessus de `warning` → warning ; sinon critical.
   */
  thresholds?: { good: number; warning: number };
  /**
   * Libellé accessible. Par défaut « 87 sur 100 ».
   * `null` si un parent annonce déjà la valeur — la barre devient alors
   * décorative et n'est plus exposée deux fois aux lecteurs d'écran.
   */
  label?: string | null;
  /** Texte substitué à la valeur brute dans l'annonce (« 87 %, objectif 90 % »). */
  valueText?: string;
  /**
   * Repère fixe sur la piste — typiquement l'OBJECTIF, dans la même unité que
   * `value`. Sans lui, une barre remplie aux trois quarts ne dit pas si le
   * quart manquant est un échec ou une avance : l'objectif n'existait que dans
   * l'annonce vocale, jamais à l'écran.
   *
   * Purement visuel : la valeur annoncée ne change pas. Passer l'objectif dans
   * `valueText` pour qu'il soit aussi énoncé.
   */
  marker?: number;
  /** Rôle ARIA — cf. `ProgressRole`. `meter` par défaut. */
  role?: ProgressRole;
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Barre de progression.
 *
 * Transposée du composant Figma `ProgressBar` (atome, niveaux Good / Warning /
 * Critical). Brique d'appui de la variante `target` de `KpiCard` : les quatre
 * cartes des maquettes en portent une.
 *
 * Le niveau ne se lit jamais à la seule couleur : la longueur du remplissage
 * porte la même information, et `aria-valuetext` la donne en toutes lettres.
 */
export function ProgressBar({
  value,
  max = 100,
  level,
  thresholds = { good: 0.9, warning: 0.6 },
  size = "md",
  label,
  marker,
  valueText,
  role = "meter",
  className,
}: ProgressBarProps) {
  const clamped = Math.min(Math.max(value, 0), max);
  const fraction = max > 0 ? clamped / max : 0;

  const resolved: ProgressLevel =
    level ??
    (fraction >= thresholds.good
      ? "good"
      : fraction >= thresholds.warning
      ? "warning"
      : "critical");

  // Un repère hors de l'échelle ne se dessine pas : il se poserait sur le bord
  // et se lirait comme une fin de piste. Aux extrêmes exacts non plus — collé
  // au bord arrondi, il disparaît dans le rayon.
  const markerFraction =
    marker !== undefined && max > 0 && marker > 0 && marker < max ? marker / max : null;

  const formatted = clamped.toLocaleString("fr-FR", { maximumFractionDigits: 1 });
  const decorative = label === null;
  const accessibleLabel = decorative ? undefined : label ?? `${formatted} sur ${max}`;

  return (
    <div
      className={cn(trackVariants({ size }), className)}
      role={decorative ? undefined : role}
      aria-hidden={decorative ? true : undefined}
      aria-label={accessibleLabel}
      aria-valuenow={decorative ? undefined : clamped}
      aria-valuemin={decorative ? undefined : 0}
      aria-valuemax={decorative ? undefined : max}
      aria-valuetext={decorative ? undefined : valueText}
    >
      <div
        className="h-full rounded-full transition-[width] duration-300 motion-reduce:transition-none"
        style={{
          width: `${fraction * 100}%`,
          // Un DÉGRADÉ, pas un aplat. C'est le geste de QORE et de Pillio : la
          // barre part plus dense et s'éclaircit vers sa pointe, ce qui lui
          // donne un sens de lecture au lieu d'un rectangle posé là.
          //
          // Le mélange se fait vers le NOIR et uniquement au départ : la
          // couleur nominale reste le point le plus clair de la barre, donc le
          // ratio mesuré contre la piste ne baisse jamais — c'est lui qui a été
          // audité, et le dégradé ne peut que l'améliorer.
          background: `linear-gradient(90deg, color-mix(in oklch, ${FILL[resolved].bg}, black 14%) 0%, ${FILL[resolved].bg} 100%)`,
          // Liseré INTÉRIEUR : il ne consomme pas de place, donc la longueur du
          // remplissage reste exactement proportionnelle à la valeur.
          boxShadow: `inset 0 0 0 1px ${FILL[resolved].edge}`,
        }}
      />
      {markerFraction !== null && (
        // Trois pixels, pas un : une FENTE de la couleur de la carte, et un
        // trait neutre au milieu.
        //
        // Le trait seul ne tient qu'un côté. Sur la piste vide il donne 5,99:1
        // en clair et 5,66:1 en sombre ; posé sur l'aplat rempli — ce qui
        // arrive dès que la valeur dépasse l'objectif — il tombe à 1,53:1 et
        // 1,18:1, c'est-à-dire invisible. La fente le détache du remplissage,
        // le trait le détache de la piste : le repère se lit où qu'il tombe.
        //
        // Un repère coloré aurait réglé le problème en en créant un autre — le
        // remplissage porte déjà le niveau par sa couleur, une seconde teinte
        // sur la même barre entrerait en concurrence avec lui.
        <span
          aria-hidden="true"
          className="absolute inset-y-0 flex w-1 -translate-x-1/2 justify-center bg-[var(--card)]"
          style={{ left: `${markerFraction * 100}%` }}
        >
          <span className="w-0.5 rounded-full bg-[var(--muted-foreground)]" />
        </span>
      )}
    </div>
  );
}

export { trackVariants as progressBarVariants };

import { type ElementType, type ReactNode } from "react";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface EmptyStateProps {
  /**
   * Ce qu'il n'y a pas, dit en clair : « Aucun avis sur cette période ».
   * Pas « Rien à afficher », qui ne dit ni quoi ni pourquoi.
   */
  title: string;
  /**
   * Élément rendu pour le titre. `p` par défaut, **volontairement** : le
   * niveau de titre dépend du plan de la page, pas du composant — même
   * raison que l'absence de `CardTitle` dans `Card`. Passer `h2`/`h3` quand
   * l'état vide remplace une région qui portait déjà un titre de ce rang.
   */
  titleAs?: "p" | "h2" | "h3" | "h4";
  /**
   * Ce qu'on peut faire pour y remédier. La règle : un état vide qui
   * n'indique pas la sortie est un cul-de-sac. « Élargissez la période ou
   * retirez le filtre par source. »
   */
  description?: string;
  /** Illustration ou icône. Décorative : le texte porte tout le sens. */
  icon?: ReactNode;
  /** Action principale — un `Button`, en général. */
  action?: ReactNode;
  /** Action secondaire, en retrait. */
  secondaryAction?: ReactNode;
  /**
   * `default` — un vide normal, attendu : aucun résultat sur ce filtre.
   * `error` — un vide subi : la donnée n'est pas arrivée.
   *
   * **Ce ton n'est pas rouge, et c'est délibéré.** Voir le composant.
   */
  tone?: "default" | "error";
  density?: "compact" | "default";
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * État vide.
 *
 * Trois choses le distinguent d'un simple message centré :
 *
 * 1. **Il nomme ce qui manque**, pas le fait qu'il manque quelque chose.
 *    « Aucun avis sur cette période » et non « Aucune donnée ».
 * 2. **Il indique la sortie.** Un état vide sans action ni consigne est un
 *    cul-de-sac : l'utilisateur voit que rien ne s'affiche, sans savoir si
 *    c'est normal, si ça va arriver, ou s'il a mal réglé quelque chose.
 * 3. **Il ne parle pas deux fois.** L'icône est décorative ; le ton se lit
 *    dans le texte, jamais à la seule couleur du cadre — ce que WCAG 1.4.1
 *    exige et qu'un liseré muet ne satisfait pas.
 *
 * ## Un échec de chargement n'est pas rouge
 *
 * Dans ce système, le rouge dit une seule chose : **l'utilisateur est
 * refusé, ou quelque chose va être détruit**. Une saisie invalide, une
 * suppression à confirmer. C'est une couleur qui qualifie un geste.
 *
 * Un chargement qui échoue ne refuse rien et ne détruit rien. Personne n'a
 * rien fait de mal, et il n'y a rien à décider : il y a un bouton à
 * cliquer. Le peindre en rouge réclame une émotion là où il faut un clic,
 * et use la couleur qui devra servir le jour où ça compte vraiment.
 *
 * | | ce qui s'est passé | couleur |
 * | --- | --- | --- |
 * | `tone="default"` | rien à montrer, c'est normal | trait tireté |
 * | `tone="error"` | la donnée n'est pas arrivée | **trait plein, sourd** |
 * | `Badge`/`InfoBanner` `tone="error"` | un fait anormal à signaler | rouge |
 * | `AlertDialog destructive` | ça va détruire | rouge |
 *
 * Ce qui distingue l'échec du vide n'est donc pas une teinte : c'est que
 * l'échec **porte une action de reprise**. Un `tone="error"` sans `action`
 * est un cul-de-sac, et la règle 2 s'applique d'abord.
 *
 * Le composant n'annonce rien de lui-même. Quand il REMPLACE un contenu qui
 * était là — après un filtre, après un rechargement — c'est au conteneur de
 * poser la région live : lui seul sait si l'apparition est un événement ou
 * l'état initial de la page.
 */
export function EmptyState({
  title,
  titleAs = "p",
  description,
  icon,
  action,
  secondaryAction,
  tone = "default",
  density = "default",
  className,
}: EmptyStateProps) {
  const Titre = titleAs as ElementType;

  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center text-center",
        "rounded-[var(--radius)] border",
        density === "compact" ? "gap-2 p-6" : "gap-3 p-10",
        tone === "error"
          ? // Trait PLEIN sur fond sourd, et aucune trace de rouge : le
            // tireté dit « emplacement en attente », le plein dit « il y a
            // quelque chose ici, et c'est ce message ». La différence entre
            // les deux tons se lit dans le texte et dans le bouton, pas dans
            // une teinte (WCAG 1.4.1).
            "border-[var(--border-strong)] bg-[var(--muted)]"
          : "border-dashed border-border bg-[var(--card)]",
        className,
      )}
    >
      {icon && (
        <span
          aria-hidden="true"
          className="text-muted-foreground [&>svg]:size-8"
        >
          {icon}
        </span>
      )}

      <Titre
        className={cn(
          "m-0 font-heading font-semibold text-foreground",
          density === "compact" ? "text-sm" : "text-base",
        )}
      >
        {title}
      </Titre>

      {description && (
        <p className="m-0 max-w-prose text-sm text-muted-foreground text-balance">
          {description}
        </p>
      )}

      {(action || secondaryAction) && (
        <div className="flex flex-wrap items-center justify-center gap-3 pt-1">
          {action}
          {secondaryAction}
        </div>
      )}
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
